/// <summary>
/// PricingAttribute of table <c>InventTable</c> field DefaultDimension.
/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableDefaultDimension extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, DefaultDimension);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Int64);
    InventTable inventTable;
    while select DefaultDimension from inventTable
        group by DefaultDimension
    {
        ret.add(inventTable.DefaultDimension);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, DefaultDimension));
    qbr.value(queryValue(_value));
}
